class LitecoinTestSuite implements TestSuiteInterface {
  final StreamController<TestSuiteStatus> _statusController = StreamController<TestSuiteStatus>.broadcast();
  TestSuiteStatus _status = TestSuiteStatus.waiting;

  @override
  String get displayName => "Litecoin";

  @override
  Widget get icon => const Icon(Icons.monetization_on, size: 32, color: Colors.grey);

  @override
  TestSuiteStatus get status => _status;

  @override
  Stream<TestSuiteStatus> get statusStream => _statusController.stream;

  void _updateStatus(TestSuiteStatus newStatus) {
    _status = newStatus;
    _statusController.add(newStatus);
  }

  @override
  Future<TestResult> runTests() async {
    try {
      _updateStatus(TestSuiteStatus.running);
      
      final stopwatch = Stopwatch()..start();
      final logs = <String>[];
      
      logs.add("Starting Litecoin test suite execution");
      
      // Get current test configuration (will be passed as parameter in the future)
      TestConfiguration? config; // TODO: Pass config as parameter to runTests()
      
      TestResult result;
      
      if (config?.mode == TestingMode.backupFile) {
        logs.add("Running backup file tests for Litecoin");
        result = await _runBackupFileTests(config!, logs);
      } else {
        logs.add("Running programmed vector tests for Litecoin");
        result = await _runProgrammedTests(logs);
      }
      
      stopwatch.stop();
      
      final finalResult = TestResult(
        success: result.success,
        message: result.message,
        logs: logs,
        executionTime: stopwatch.elapsed,
      );
      
      _updateStatus(finalResult.success ? TestSuiteStatus.passed : TestSuiteStatus.failed);
      return finalResult;
      
    } catch (e, stack) {
      _updateStatus(TestSuiteStatus.failed);
      Logging.instance.log("Litecoin test suite failed: $e", level: LogLevel.error, printFullLength: true);
      Logging.instance.log("Stack trace: $stack", level: LogLevel.error, printFullLength: true);
      
      return TestResult(
        success: false,
        message: "Litecoin test suite failed: $e",
        logs: ["Error: $e"],
        executionTime: Duration.zero,
      );
    }
  }

  Future<TestResult> _runProgrammedTests(List<String> logs) async {
    try {
      logs.add("Testing Litecoin wallet creation and address generation");
      
      // Test 1: Basic wallet creation and address generation
      if (!await _testBasicWalletCreation(logs)) {
        return TestResult(
          success: false,
          message: "Basic wallet creation test failed",
          logs: logs,
          executionTime: Duration.zero,
        );
      }
      
      // Test 2: Scrypt algorithm validation
      logs.add("Testing Litecoin Scrypt algorithm validation");
      if (!await _testScryptAlgorithmValidation(logs)) {
        return TestResult(
          success: false,
          message: "Scrypt algorithm validation failed",
          logs: logs,
          executionTime: Duration.zero,
        );
      }
      
      // Test 3: SegWit support testing  
      logs.add("Testing Litecoin SegWit support");
      if (!await _testSegWitSupport(logs)) {
        logs.add("SegWit support test failed - continuing with other tests");
      }
      
      // Test 4: Fast block time validation (2.5 minutes)
      logs.add("Testing Litecoin block time validation");
      if (!await _testBlockTimeValidation(logs)) {
        logs.add("Block time validation failed - continuing with other tests");
      }
      
      // Test 5: Address format validation (L addresses)
      logs.add("Testing Litecoin address format validation");
      if (!await _testAddressFormatValidation(logs)) {
        return TestResult(
          success: false,
          message: "Address format validation failed",
          logs: logs,
          executionTime: Duration.zero,
        );
      }
      
      // Test 6: Transaction fee calculation
      logs.add("Testing Litecoin transaction fee calculation");
      if (!await _testTransactionFeeCalculation(logs)) {
        logs.add("Transaction fee calculation test failed - continuing with other tests");
      }
      
      logs.add("All Litecoin core tests completed successfully");
      return TestResult(
        success: true,
        message: "Litecoin test suite completed successfully",
        logs: logs,
        executionTime: Duration.zero,
      );
      
    } catch (e) {
      logs.add("Litecoin programmed tests failed: $e");
      return TestResult(
        success: false,
        message: "Litecoin programmed tests failed: $e",
        logs: logs,
        executionTime: Duration.zero,
      );
    }
  }

  Future<TestResult> _runBackupFileTests(TestConfiguration config, List<String> logs) async {
    try {
      logs.add("Starting Litecoin backup file restoration tests");
      
      // Step 1: Load and validate backup file
      final backupHandler = BackupFileHandler();
      final backupData = await backupHandler.loadBackupFile(
        config.backupFilePath!,
        config.backupPassphrase,
      );
      
      if (backupData == null) {
        return TestResult(
          success: false,
          message: "Failed to load Litecoin backup file",
          logs: logs,
          executionTime: Duration.zero,
        );
      }
      
      logs.add("Backup file loaded successfully");
      
      // Step 2: Filter for Litecoin wallets
      final litecoinWallets = backupData.wallets.where((w) => 
        w.coin.toLowerCase().contains('litecoin') && !w.coin.toLowerCase().contains('mweb')).toList();
      
      if (litecoinWallets.isEmpty) {
        logs.add("No standard Litecoin wallets found in backup file");
        return TestResult(
          success: true,
          message: "No Litecoin wallets to test",
          logs: logs,
          executionTime: Duration.zero,
        );
      }
      
      logs.add("Found ${litecoinWallets.length} Litecoin wallet(s) in backup");
      
      // Step 3: Restore and test each wallet
      final restorationManager = WalletRestorationManager();
      final transactionExecutor = TransactionTestExecutor();
      
      int walletsRestored = 0;
      int transactionsAttempted = 0;
      int transactionsSuccessful = 0;
      final List<String> transactionIds = [];
      final Map<String, String> walletErrors = {};
      
      for (final walletData in litecoinWallets) {
        try {
          logs.add("Restoring Litecoin wallet: ${walletData.name}");
          
          final wallet = await restorationManager.restoreWallet(
            walletData,
            Litecoin(CryptoCurrencyNetwork.main),
          );
          
          if (wallet != null) {
            walletsRestored++;
            logs.add("Successfully restored wallet: ${walletData.name}");
            
            // Test a small self-spend transaction
            logs.add("Testing self-spend transaction for ${walletData.name}");
            transactionsAttempted++;
            
            final txResult = await transactionExecutor.executeSelfSpendTransaction(
              wallet,
              config.testAmount ?? "100000", // 100000 litoshis (0.001 LTC)
              config.feeRate ?? 1,
            );
            
            if (txResult.success && txResult.transactionId != null) {
              transactionsSuccessful++;
              transactionIds.add(txResult.transactionId!);
              logs.add("Self-spend transaction successful: ${txResult.transactionId}");
            } else {
              logs.add("Self-spend transaction failed: ${txResult.errorMessage}");
            }
          } else {
            walletErrors[walletData.name] = "Failed to restore wallet";
            logs.add("Failed to restore wallet: ${walletData.name}");
          }
        } catch (e) {
          walletErrors[walletData.name] = e.toString();
          logs.add("Error testing wallet ${walletData.name}: $e");
        }
      }
      
      final success = walletsRestored > 0 && walletErrors.isEmpty;
      final message = success 
        ? "Litecoin backup tests completed successfully"
        : "Some Litecoin backup tests failed";
      
      return BackupTestResult(
        success: success,
        message: message,
        logs: logs,
        executionTime: Duration.zero,
        walletsRestored: walletsRestored,
        transactionsAttempted: transactionsAttempted,
        transactionsSuccessful: transactionsSuccessful,
        transactionIds: transactionIds,
        walletErrors: walletErrors,
      );
      
    } catch (e) {
      logs.add("Litecoin backup file tests failed: $e");
      return TestResult(
        success: false,
        message: "Litecoin backup file tests failed: $e",
        logs: logs,
        executionTime: Duration.zero,
      );
    }
  }

  Future<bool> _testBasicWalletCreation(List<String> logs) async {
    try {
      logs.add("Creating test Litecoin wallet with mnemonic");
      
      // Use the standard test mnemonic
      const testMnemonic = "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about";
      
      // Test wallet creation
      final litecoin = Litecoin(CryptoCurrencyNetwork.main);
      logs.add("Litecoin currency initialized: ${litecoin.prettyName}");
      
      // Validate basic properties
      if (litecoin.ticker != "LTC") {
        logs.add("Invalid ticker: expected LTC, got ${litecoin.ticker}");
        return false;
      }
      
      if (litecoin.identifier != "litecoin") {
        logs.add("Invalid identifier: expected litecoin, got ${litecoin.identifier}");
        return false;
      }
      
      logs.add("Litecoin basic properties validated successfully");
      logs.add("Ticker: ${litecoin.ticker}, ID: ${litecoin.identifier}");
      
      return true;
    } catch (e) {
      logs.add("Basic wallet creation test failed: $e");
      return false;
    }
  }

